"""A small standalone YAML reader and writer for site configuration and metadata.

The reader keeps source locations, which also makes validation diagnostics useful.
No external parser or site-generator code is used.
"""
import json
import re

class YamlError(ValueError):
    def __init__(self, message, line=1, column=1):
        self.message, self.line, self.column = message, line, column
        super().__init__(message)

class LocatedDict(dict):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.locations = {}
        self.location = (1,1)

class LocatedList(list):
    def __init__(self, *args):
        super().__init__(*args)
        self.locations = {}
        self.location = (1,1)


def split_unquoted(s, delimiter=','):
    out=[]; start=0; quote=None; depth=0; i=0
    while i < len(s):
        c=s[i]
        if quote:
            if c=='\\' and quote=='"': i+=2; continue
            if c==quote:
                if quote=="'" and i+1<len(s) and s[i+1]==quote: i+=2;continue
                quote=None
        elif c in "\"'": quote=c
        elif c in '[{(':depth+=1
        elif c in ']})':depth-=1
        elif c==delimiter and depth==0:
            out.append(s[start:i]);start=i+1
        i+=1
    out.append(s[start:])
    return out

def split_pair(s):
    quote=None;depth=0;i=0
    while i<len(s):
        c=s[i]
        if quote:
            if c=='\\' and quote=='"':i+=2;continue
            if c==quote:
                if quote=="'" and i+1<len(s) and s[i+1]==quote:i+=2;continue
                quote=None
        elif c in "\"'":quote=c
        elif c in '[{':depth+=1
        elif c in ']}':depth-=1
        elif c==':' and depth==0 and (i+1==len(s) or s[i+1].isspace()):return s[:i],s[i+1:],i
        i+=1
    return None

def uncomment(s):
    quote=None;i=0
    while i<len(s):
        c=s[i]
        if quote:
            if c=='\\' and quote=='"':i+=2;continue
            if c==quote:
                if quote=="'" and i+1<len(s) and s[i+1]==quote:i+=2;continue
                quote=None
        elif c in "\"'" and (i==0 or s[i-1].isspace() or s[i-1] in '[{:,'):quote=c
        elif c=='#' and (i==0 or s[i-1].isspace()):return s[:i].rstrip()
        i+=1
    return s.rstrip()

class Reader:
    def __init__(self, text):
        self.lines=text.replace('\r\n','\n').replace('\r','\n').split('\n')
        self.i=0
        self.anchors={}

    def skip(self):
        while self.i<len(self.lines):
            s=self.lines[self.i].strip()
            if not s or s.startswith('#') or s in ['---','...']:
                self.i+=1
            else:break

    def scalar(self,s,line=1,column=1):
        s=uncomment(s.strip())
        if s.startswith('&'):
            m=re.match(r'&([^\s]+)\s*(.*)',s)
            value=self.scalar(m[2],line,column);self.anchors[m[1]]=value;return value
        if s.startswith('*') and s[1:] in self.anchors:return self.anchors[s[1:]]
        if not s or s in ['null','Null','NULL','~']:return None
        if s in ['true','True','TRUE']:return True
        if s in ['false','False','FALSE']:return False
        if s[0] in "\"'":
            if len(s)<2 or s[-1]!=s[0]:raise YamlError('found unexpected end of stream',line,column)
            if s[0]=="'":return s[1:-1].replace("''","'")
            try:return json.loads(s)
            except Exception:
                return re.sub(r'\\(.)',lambda m:{'n':'\n','r':'\r','t':'\t','0':'\0'}.get(m[1],m[1]),s[1:-1])
        if s[0]=='[':
            # Keep even an unfinished sequence typed, for a useful field diagnostic.
            t=s[1:-1] if s.endswith(']') else s[1:]
            vals=LocatedList();vals.location=(line,column)
            start=0
            for v in split_unquoted(t):
                if v.strip():
                    vals.locations[len(vals)]=(line,column+1+start+len(v)-len(v.lstrip()))
                    vals.append(self.scalar(v,line,column+1+start))
                start+=len(v)+1
            return vals
        if s[0]=='{':
            vals=LocatedDict();vals.location=(line,column)
            for v in split_unquoted(s[1:-1]):
                if not v.strip():continue
                p=split_pair(v)
                if not p:
                    if ':' not in v: vals[self.scalar(v)]=None;continue
                    a,b=v.split(':',1);p=(a,b,len(a))
                k=self.scalar(p[0]);vals[k]=self.scalar(p[1],line,column+p[2]+2);vals.locations[k]=(line,column+p[2]+2)
            return vals
        n=s.replace('_','')
        try:
            if re.match(r'^[+-]?\d+$',n):return int(n)
            if re.match(r'^[+-]?0x[0-9a-fA-F]+$',n):return int(n,16)
            if re.match(r'^[+-]?0o[0-7]+$',n):return int(n,8)
            if re.match(r'^[+-]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][+-]?\d+)?$',n):return float(n)
        except ValueError:pass
        return s

    def block_scalar(self, marker, parent_indent):
        start=self.i;indent=None
        for j in range(start,len(self.lines)):
            line=self.lines[j]
            if not line.strip():continue
            n=len(line)-len(line.lstrip(' '))
            if n<=parent_indent:break
            indent=n;break
        if indent is None:return ''
        chunks=[]
        while self.i<len(self.lines):
            line=self.lines[self.i]
            if line.strip() and len(line)-len(line.lstrip(' '))<indent:break
            chunks.append(line[indent:] if line.strip() else '')
            self.i+=1
        # The split operation represents the final newline by an extra empty item.
        if self.i==len(self.lines) and chunks and chunks[-1]=='':chunks.pop()
        if marker.startswith('>'):
            value=''
            for j,line in enumerate(chunks):
                value+=line
                if j+1<len(chunks):
                    if line and chunks[j+1] and not line.startswith(' ') and not chunks[j+1].startswith(' '):value+=' '
                    else:value+='\n'
            value+='\n' if chunks else ''
        else:value='\n'.join(chunks)+('\n' if chunks else '')
        if '-' in marker:return value.rstrip('\n')
        if '+' in marker:return value
        return value.rstrip('\n')+'\n' if value else ''

    def value(self, raw, line, column, parent_indent):
        raw=uncomment(raw).strip()
        if raw and raw[0] in '|>' and re.match(r'^[|>][+\-0-9]*$',raw):return self.block_scalar(raw,parent_indent)
        if raw:
            if raw.startswith('&') and len(raw.split())==1:
                v=self.value('',line,column,parent_indent);self.anchors[raw[1:]]=v;return v
            return self.scalar(raw,line,column)
        self.skip()
        if self.i>=len(self.lines):return None
        s=self.lines[self.i];n=len(s)-len(s.lstrip(' '))
        if n>parent_indent or (n==parent_indent and re.match(r'^-(?:\s|$)',s[n:])):
            return self.node(n)
        return None

    def node(self,indent):
        self.skip()
        if self.i>=len(self.lines):return None
        s=self.lines[self.i][indent:]
        islist=bool(re.match(r'^-(?:\s|$)',s))
        if not islist and not split_pair(uncomment(s)):
            line=self.i+1;self.i+=1;return self.scalar(s,line,indent+1)
        out=LocatedList() if islist else LocatedDict();out.location=(self.i+1,indent+1)
        while self.i<len(self.lines):
            self.skip()
            if self.i>=len(self.lines):break
            rawline=self.lines[self.i];n=len(rawline)-len(rawline.lstrip(' '))
            if n!=indent:break
            s=uncomment(rawline[indent:]);line=self.i+1
            if islist:
                m=re.match(r'^-\s*(.*)$',s)
                if not m:break
                rest=m[1];col=indent+len(s)-len(rest)+1
                self.i+=1
                if re.match(r'^-(?:\s|$)',rest):
                    # Rewrite compact nested sequences as an ordinary nested block.
                    self.i-=1;self.lines[self.i]=' '*(col-1)+rest
                    v=self.node(col-1)
                elif split_pair(rest):
                    pair=split_pair(rest);d=LocatedDict();d.location=(line,col)
                    k=self.scalar(pair[0],line,col);rhs=pair[1];vcol=col+pair[2]+1+len(rhs)-len(rhs.lstrip())
                    d[k]=self.value(rhs,line,vcol,col-1);d.locations[k]=(line,vcol)
                    self.skip()
                    if self.i<len(self.lines):
                        nxt=self.lines[self.i];nn=len(nxt)-len(nxt.lstrip(' '))
                        if nn>indent:
                            more=self.node(nn)
                            if isinstance(more,dict):d.update(more);d.locations.update(more.locations)
                    v=d
                else:v=self.value(rest,line,col,indent)
                out.locations[len(out)]=(line,col);out.append(v)
            else:
                pair=split_pair(s)
                if not pair:raise YamlError('could not find expected \':\'',line,indent+1)
                k=self.scalar(pair[0],line,indent+1);rhs=pair[1];col=indent+pair[2]+2+len(rhs)-len(rhs.lstrip())
                self.i+=1
                v=self.value(rhs,line,col,indent)
                if k=='<<' and isinstance(v,dict):
                    for kk,vv in v.items():out.setdefault(kk,vv)
                else:out[k]=v;out.locations[k]=(line,col if rhs.strip() else (getattr(v,'location',(line,col))[1]))
                if not rhs.strip() and hasattr(v,'location'):out.locations[k]=v.location
        return out

    def parse(self):
        self.skip()
        if self.i==len(self.lines):return None
        indent=len(self.lines[self.i])-len(self.lines[self.i].lstrip(' '))
        return self.node(indent)

def load(s):return Reader(s).parse()

def scalar_dump(v):
    if v is None:return 'null'
    if v is True:return 'true'
    if v is False:return 'false'
    if isinstance(v,(int,float)):return str(v)
    s=str(v)
    if s=='':return "''"
    if '\n' in s or '\r' in s or '\t' in s:return json.dumps(s,ensure_ascii=False)
    if s.strip()!=s or s.lower() in ['null','true','false','~'] or re.match(r'^[-+]?\d',s) or s[0] in '%@`[]{},*&!|>\'"?#' or ': ' in s or ' #' in s or s.endswith(':'):
        return "'"+s.replace("'","''")+"'"
    return s

def dump(value,indent=0):
    prefix=' '*indent;lines=[]
    if isinstance(value,dict):
        if not value:return prefix+'{}\n'
        for key,v in value.items():
            k=scalar_dump(key)
            if isinstance(v,dict) and v:
                lines.append(prefix+k+':\n'+dump(v,indent+2))
            elif isinstance(v,list) and v:
                lines.append(prefix+k+':\n'+dump(v,indent))
            elif isinstance(v,dict):lines.append(prefix+k+': {}\n')
            elif isinstance(v,list):lines.append(prefix+k+': []\n')
            else:lines.append(prefix+k+': '+scalar_dump(v)+'\n')
    elif isinstance(value,list):
        if not value:return prefix+'[]\n'
        for v in value:
            if isinstance(v,(dict,list)) and v:
                rendered=dump(v,indent+2);lines.append(prefix+'- '+rendered[indent+2:])
            elif isinstance(v,dict):lines.append(prefix+'- {}\n')
            elif isinstance(v,list):lines.append(prefix+'- []\n')
            else:lines.append(prefix+'- '+scalar_dump(v)+'\n')
    else:lines.append(prefix+scalar_dump(value)+'\n')
    return ''.join(lines)
