"""Create a self-contained Python executable; no third-party packages are needed."""
import pathlib
import py_compile
import tempfile
import zipfile

root = pathlib.Path(__file__).resolve().parent
with tempfile.TemporaryDirectory() as temp:
    for source in (root / 'replica').rglob('*.py'):
        py_compile.compile(str(source), cfile=str(pathlib.Path(temp) / (source.stem + '.pyc')), doraise=True)
out = root / 'executable'
with out.open('wb') as target:
    target.write(b'#!/usr/bin/env python3\n')
with zipfile.ZipFile(out, 'a', compression=zipfile.ZIP_DEFLATED) as archive:
    archive.writestr('__main__.py', 'from replica.cli import main\nmain()\n')
    for source in sorted((root / 'replica').rglob('*')):
        if source.is_file() and '__pycache__' not in source.parts and source.suffix != '.pyc':
            archive.write(source, source.relative_to(root))
out.chmod(0o755)
