import datetime as dt
import html
import json
import re
import unicodedata
from html.parser import HTMLParser


def slugify(value):
    s=str(value)
    s=s.replace('ß','ss').replace('Æ','AE').replace('æ','ae').replace('Ø','O').replace('ø','o').replace('Ł','L').replace('ł','l').replace('Ð','D').replace('ð','d').replace('Þ','Th').replace('þ','th')
    s=unicodedata.normalize('NFKD',s)
    s=''.join(c for c in s if not unicodedata.combining(c))
    s=s.encode('ascii','ignore').decode('ascii').lower()
    return re.sub(r'[^a-z0-9]+','-',s).strip('-')

def json_text(v,pretty=False):
    return json.dumps(v,ensure_ascii=False,indent=2 if pretty else None,separators=None if pretty else (',',':'),allow_nan=False)

class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts=[]
        self.skip=0
    def handle_starttag(self,tag,attrs):
        if tag in ('script','style'):self.skip+=1
        if tag in ('p','br','li','div','h1','h2','h3','h4','h5','h6','pre','tr','hr'):self.parts.append(' ')
    def handle_endtag(self,tag):
        if tag in ('script','style'):self.skip=max(0,self.skip-1)
        if tag in ('p','li','div','h1','h2','h3','h4','h5','h6','pre','tr'):self.parts.append(' ')
    def handle_data(self,data):
        if not self.skip:self.parts.append(data)

def plain_text(s):
    parser=TextExtractor()
    try:parser.feed(s or '');return ' '.join(''.join(parser.parts).split())
    except Exception:return ' '.join(re.sub(r'<[^>]*>','',s or '').split())

def strip_tags(s):
    # Template excerpts strip tags but retain line boundaries and entities.
    return re.sub(r'<[^>]*>','',str(s or ''))

def parse_datetime(s):
    if isinstance(s,(float,int)):return dt.datetime.fromtimestamp(s,dt.timezone.utc).replace(tzinfo=None)
    if isinstance(s,dt.datetime):return s
    return dt.datetime.fromisoformat(str(s).replace('Z','+00:00'))

def date_format(s,fmt='%Y-%m-%d'):
    if not s:return ''
    try:
        d=parse_datetime(s)
        if d.tzinfo is None:d=d.replace(tzinfo=dt.timezone.utc)
        rep={'%+':d.isoformat(timespec='seconds'),'%:z':d.strftime('%z')[:3]+':'+d.strftime('%z')[3:],'%s':str(int(d.timestamp()))}
        for k,v in rep.items():fmt=fmt.replace(k,v)
        return d.strftime(fmt)
    except Exception:return str(s)

def rust_debug_string(s):return json.dumps(str(s),ensure_ascii=False)
