"""Read content files, metadata, dates, document links, and Markdown fragments."""
import copy
import datetime as dt
import json
import re
from pathlib import Path
from . import yamlio
from .markdown import Markdown
from .config import scalar_string
from .util import slugify

class BadFrontmatter(Exception):pass
class BadDate(Exception):
    def __init__(self,date,path,reason):self.date,self.path,self.reason=date,path,reason


def blank_content():
    return {'title':'','description':None,'slug':'','html':'','tags':[],'date':None,'extra':None,
        'links_to':None,'back_links':[],'card_image':None,'banner_image':None,'authors':[],
        'stream':None,'series':None,'pinned':False,'toc':None,'modified_time':None,
        'comments':None,'next':None,'previous':None,'source_path':None}


def value_debug(v):
    return json.dumps(v,ensure_ascii=False,separators=(', ', ': '))


def first_title(text):
    lines=text.strip().splitlines()
    if not lines:return '', ''
    first=lines[0].lstrip('#').strip()
    return first,'\n'.join(lines[1:])


def frontmatter(text):
    text=text.lstrip('\ufeff')
    if not text.startswith('---'):return {},text
    match=re.match(r'^---[^\S\n]*\r?\n([\s\S]*?)\r?\n---[^\S\n]*(?:\r?\n|$)',text)
    if not match:raise BadFrontmatter()
    try:meta=yamlio.load(match[1])
    except Exception:raise BadFrontmatter()
    if not isinstance(meta,dict) or not meta:raise BadFrontmatter()
    for k,v in meta.items():
        if k!='extra' and isinstance(v,dict):raise BadFrontmatter()
        if isinstance(v,list) and any(isinstance(x,(dict,list)) for x in v):raise BadFrontmatter()
    return meta,text[match.end():]


def metadata_list(value):
    if isinstance(value,list):return [str(x) if isinstance(x,str) else scalar_string(x) for x in value]
    if isinstance(value,str):return [x.strip() for x in value.split(',') if x.strip()]
    return []


def date_value(value,path):
    if not isinstance(value,str):return None
    s=value.strip()
    formats=['%Y-%m-%d %H:%M:%S','%Y-%m-%d %H:%M','%Y-%m-%d']
    for fmt in formats:
        try:return dt.datetime.strptime(s,fmt).isoformat(timespec='seconds')
        except ValueError:pass
    try:
        if len(s)>=10 and re.match(r'^\d{4}-\d{2}-\d{2}',s):return dt.datetime.strptime(s[:10],'%Y-%m-%d').isoformat(timespec='seconds')
    except ValueError:pass
    if len(s)<10:reason='premature end of input'
    elif re.match(r'^\d{4}-\d{2}-\d{2}',s):reason='input is out of range'
    else:reason='input contains invalid characters'
