    c['series']=meta.get('series') if isinstance(meta.get('series'),str) else None
    c['tags']=metadata_list(meta.get('tags'))
    c['authors']=metadata_list(meta.get('authors')) or metadata_list(meta.get('author')) or metadata_list(site.get('default_author'))
    if 'description' in meta:c['description']=value_debug(meta['description'])
    if 'card_image' in meta:c['card_image']=value_debug(meta['card_image'])
