"""Configuration defaults, validation, and CLI overrides."""
import copy
import json
from pathlib import Path
from . import data, yamlio
from .markdown import PARSER_DEFAULTS
from .util import json_text

class ConfigError(Exception):
    def __init__(self,message,line=1,column=1):
        self.message,self.line,self.column=message,line,column
    def __str__(self):
        return 'Error('+json.dumps(self.message,ensure_ascii=False)+f', line: {self.line}, column: {self.column})'


def defaults(generated=False):
    cfg=yamlio.load(data.text('config.yaml'))
    # Serializing command options and loading a site have distinct default values.
    if not generated:
        cfg['language']='en';cfg['enable_related_content']=True;cfg['search_title']='Search'
    return dict(cfg)


def scalar_string(v):
    if v is None:return 'null'
    if isinstance(v,bool):return 'true' if v else 'false'
    return str(v)

def type_name(v):
    if v is None:return 'unit value'
    if v is True:return 'boolean `true`'
    if v is False:return 'boolean `false`'
    if isinstance(v,str):return 'string '+json.dumps(v,ensure_ascii=False)
    if isinstance(v,int):return 'integer `'+str(v)+'`'
    if isinstance(v,float):return 'floating point `'+str(v)+'`'
    if isinstance(v,list):return 'sequence'
    if isinstance(v,dict):return 'map'
    return str(type(v))


def location(container,key=None):
    if key is not None and hasattr(container,'locations') and key in container.locations:return container.locations[key]
    return getattr(container,'location',(1,1))

class Validator:
    def fail(self,path,msg,parent=None,key=None):
        line,col=location(parent,key)
        raise ConfigError((path+': ' if path else '')+msg,line,col)
    def string(self,v,path,parent,key,optional=False):
        if optional and v is None:return None
        if isinstance(v,(list,dict)):self.fail(path,'invalid type: '+type_name(v)+', expected a string',parent,key)
        return scalar_string(v)
    def boolean(self,v,path,parent,key,optional=False):
        if optional and v is None:return None
        if not isinstance(v,bool):self.fail(path,'invalid type: '+type_name(v)+', expected a boolean',parent,key)
        return v
    def number(self,v,path,parent,key):
        if not isinstance(v,int) or isinstance(v,bool) or v<0:self.fail(path,'invalid type: '+type_name(v)+', expected usize',parent,key)
        return v
    def mapping(self,v,path,parent,key,struct=None):
        if not isinstance(v,dict):self.fail(path,'invalid type: '+type_name(v)+', expected '+('struct '+struct if struct else 'a map'),parent,key)
        return v
    def sequence(self,v,path,parent,key):
        if not isinstance(v,list):self.fail(path,'invalid type: '+type_name(v)+', expected a sequence',parent,key)
        return v
    def pairs(self,v,path,parent,key):
        v=self.sequence(v,path,parent,key);out=[]
        for i,item in enumerate(v):
            self.sequence(item,path+f'[{i}]',v,i)
            if len(item)!=2:self.fail(path+f'[{i}]',f'invalid length {len(item)}, expected sequence of 2 elements',v,i)
            out.append([self.string(x,path+f'[{i}][{j}]',item,j) for j,x in enumerate(item)])
        return out
    def config(self,v):
        cfg=defaults()
        if v is None:return cfg
        self.mapping(v,'',v,None,'Marmite')
        optional=['https','source_repository','image_provider','theme','shortcode_pattern']
        for k,default in cfg.items():
            if k not in v:continue
            value=v[k]
            if isinstance(default,str) or k in ('source_repository','image_provider','theme','shortcode_pattern'):
                cfg[k]=self.string(value,k,v,k,k in optional)
            elif isinstance(default,bool) or k=='https':cfg[k]=self.boolean(value,k,v,k,k=='https')
            elif isinstance(default,int):cfg[k]=self.number(value,k,v,k)
            elif k=='menu':cfg[k]=self.pairs(value,k,v,k)
            elif k=='extra':cfg[k]=copy.deepcopy(value)
            elif k in ('authors','streams','series'):
                values=self.mapping(value,k,v,k);result={}
                required='name' if k=='authors' else 'display_name'
                struct={'authors':'Author','streams':'Stream','series':'Series'}[k]
                for username,attrs in values.items():
                    path=k+'.'+str(username);self.mapping(attrs,path,values,username,struct)
                    if required not in attrs:self.fail(path,'missing field `'+required+'`',values,username)
                    item={required:self.string(attrs[required],path+'.'+required,attrs,required)}
                    if k=='authors':
                        for fld in ['avatar','bio']:item[fld]=self.string(attrs[fld],path+'.'+fld,attrs,fld,True) if fld in attrs else None
                        item['links']=self.pairs(attrs['links'],path+'.links',attrs,'links') if attrs.get('links') is not None else None
                    elif k=='series':item['description']=self.string(attrs['description'],path+'.description',attrs,'description',True) if 'description' in attrs else None
                    result[scalar_string(username)]=item
                cfg[k]=result
            elif k=='file_mapping':
                items=self.sequence(value,k,v,k);result=[]
                for i,item in enumerate(items):
                    p=k+f'[{i}]';self.mapping(item,p,items,i,'FileMapping')
                    for fld in ['source','dest']:
                        if fld not in item:self.fail(p,'missing field `'+fld+'`',items,i)
                    result.append({f:self.string(item[f],p+'.'+f,item,f) for f in ['source','dest']})
                cfg[k]=result
            elif k=='markdown_parser':
                if value is None:cfg[k]=None;continue
                self.mapping(value,k,v,k,'ParserOptions');opts=copy.deepcopy(PARSER_DEFAULTS)
                for section,vals in opts.items():
                    if section not in value:continue
                    self.mapping(value[section],k+'.'+section,value,section,section.title()+'Options')
                    for key in vals:
                        if key in value[section]:opts[section][key]=self.boolean(value[section][key],k+'.'+section+'.'+key,value[section],key)
                cfg[k]=opts
        if not cfg['language']:cfg['language']='en'
        if not cfg['search_title']:cfg['search_title']='Search'
        return cfg


def apply_options(cfg,opts):
    for key,val in opts.items():
        if key in cfg:cfg[key]=val
    if 'colorscheme' in opts:
        if not isinstance(cfg['extra'],dict):cfg['extra']={}
        cfg['extra']['colorscheme']=opts['colorscheme']
    return cfg


def read_config(path,opts,log):
    try:raw=Path(path).read_text(encoding='utf-8')
    except (OSError,UnicodeError) as exc:
        log('INFO','marmite::site',f"Unable to read '{path}', assuming defaults.: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}")
        log('INFO','marmite::site','Config loaded from: defaults')
        return apply_options(defaults(),opts)
    try:parsed=yamlio.load(raw);cfg=Validator().config(parsed)
    except yamlio.YamlError as exc:raise ConfigError(exc.message,exc.line,exc.column)
    log('INFO','marmite::site','Config loaded from: '+str(path))
    return apply_options(cfg,opts)
