"""Site collection, navigation, serialization, and publication."""
import copy
import datetime as dt
import email.utils
import json
import math
import os
import re
import shutil
import time
import urllib.parse
from pathlib import Path
from . import data
from .config import read_config, ConfigError
from .content import read_content, read_404, BadFrontmatter, BadDate
from .markdown import Markdown, escape
from .template import Engine, TemplateError, Undefined
from .util import slugify, date_format, json_text, plain_text

URL_KINDS=['posts','pages','tags','authors','series','streams','archives','feeds','pagination','file_mappings','misc']

class SiteError(Exception):pass


def os_debug(exc):
    mapping={2:'NotFound',13:'PermissionDenied',17:'AlreadyExists',20:'NotADirectory',21:'IsADirectory',22:'InvalidInput'}
    return 'Os { code: '+str(getattr(exc,'errno',2) or 2)+', kind: '+mapping.get(getattr(exc,'errno',2),'Other')+', message: '+json.dumps(getattr(exc,'strerror',str(exc)))+' }'

class Site:
    def __init__(self,input_dir,output_dir,options,log):
        self.input=input_dir;self.output=output_dir;self.options=options;self.log=log
        self.config_path=os.path.join(input_dir,options.get('config','marmite.yaml'))
        self.cfg=read_config(self.config_path,options,log)
        self.content_dir=os.path.join(input_dir,self.cfg['content_path'])
        if not os.path.isdir(self.content_dir):self.content_dir=input_dir
        self.output_site=os.path.join(output_dir,self.cfg['site_path']) if self.cfg['site_path'] else output_dir
        self.fragments={};self.raw_fragments={};self.posts=[];self.pages=[];self.groups={}
        self.ctx={};self.site_data={};self.engine=None;self.generated_urls={k:[] for k in URL_KINDS}
        self.theme_dir=None;self.start_time=time.perf_counter();self.now=dt.datetime.now(dt.timezone.utc)
        self._init_theme()
    def _init_theme(self):
        if not self.cfg.get('theme'):return
        theme=self.cfg['theme'];p=os.path.join(self.input,theme)
        if not os.path.isdir(p):
            msg="Theme folder '"+p+"' does not exist"
            self.log('ERROR','marmite::config',msg);self.log('ERROR','marmite::config',msg);raise SiteError()
        self.theme_dir=p
        manifest=os.path.join(p,'theme.json')
        if os.path.isfile(manifest):
            try:theme_data=json.load(open(manifest,encoding='utf-8'))
            except Exception:theme_data={}
            # A theme's configured paths refer to directories inside its folder.
        self.cfg['templates_path']=os.path.join(theme,'templates')
        self.cfg['static_path']=os.path.join(theme,'static')

    def collect(self):
        for name in ['markdown_header','markdown_footer','references']:
            p=os.path.join(self.content_dir,'_'+name+'.md')
            try:self.fragments[name]=Path(p).read_text(encoding='utf-8')
            except (OSError,UnicodeError):self.fragments[name]=''
        for name in ['header','footer','hero','sidebar','announce','htmlhead','htmltail','comments']:
            p=os.path.join(self.content_dir,'_'+name+'.md')
            if os.path.isfile(p):
                try:self.raw_fragments[name]=Path(p).read_text(encoding='utf-8')
                except (OSError,UnicodeError):pass
        paths=[]
        output_abs=os.path.abspath(self.output)
        for root,dirs,files in os.walk(self.content_dir):
            dirs[:]=[d for d in dirs if os.path.abspath(os.path.join(root,d))!=output_abs and not os.path.islink(os.path.join(root,d))]
            for name in files:
                if name.endswith('.md') and not name.startswith('_'):
                    paths.append(os.path.join(root,name))
        entries=[]
        for p in sorted(paths,reverse=True):
            try:c=read_content(p,self.cfg,self.fragments,self.log)
            except BadFrontmatter:
                self.log('ERROR','marmite::site','Failed to process content: "Invalid front matter format"');continue
            except BadDate as e:
                self.log('ERROR','marmite::content',f'ERROR: Invalid date format {e.date} when parsing {e.path}, {e.reason}');raise SiteError()
            except (OSError,UnicodeError):continue
            entries.append(c)
        self.posts=sorted((c for c in entries if c['date']),key=lambda c:(c['date'],c['source_path']),reverse=True)
        self.pages=[c for c in entries if not c['date']]
        self.groups={k:{} for k in ['tag','archive','author','stream','series']}
        for c in self.posts:
            for tag in c['tags']:
                self.groups['tag'].setdefault(tag,[]).append(c)
                alias=slugify(tag)
                if alias!=tag:self.groups['tag'].setdefault(alias,[]).append(c)
            self.groups['archive'].setdefault(c['date'][:4],[]).append(c)
            for author in c['authors']:self.groups['author'].setdefault(author,[]).append(c)
            if c['stream'] is not None:self.groups['stream'].setdefault(c['stream'],[]).append(c)
            if c['series'] is not None:self.groups['series'].setdefault(c['series'],[]).append(c)
        # Snapshots stop the adjacent/backlink relationships from being recursive.
        snapshots={id(c):copy.deepcopy(c) for c in entries}
        if self.cfg['enable_related_content']:
            for c in entries:
                for link in c['links_to'] or []:
                    for target in entries:
                        if target['slug']==link and c['slug']!=target['slug']:
                            if all(x['slug']!=c['slug'] for x in target['back_links']):target['back_links'].append(snapshots[id(c)])
        if self.cfg['show_next_prev_links']:
            collections=[]
            for name,items in self.groups['series'].items():collections.append(items)
            for name,items in self.groups['stream'].items():collections.append([c for c in items if not c['series']])
            for items in collections:
                ordered=sorted(items,key=lambda c:(c['date'] or '',c['source_path'] or ''))
                for i,c in enumerate(ordered):
                    if i:c['previous']=snapshots[id(ordered[i-1])]
                    if i+1<len(ordered):c['next']=snapshots[id(ordered[i+1])]
        self.create_urls()
        self.site_data={
            'site':self.cfg,'posts':self.posts,'pages':self.pages,
            **{k:{'kind':k.title(),'map':v} for k,v in self.groups.items()},
            'latest_timestamp':None,'config_path':self.config_path,'force_render':self.options.get('force',False),
            'generated_urls':self.generated_urls,'galleries':{},
        }
        self.ctx={'language':self.cfg['language'],'markdown_fragments':self.fragments,'menu':self.cfg['menu'],
                  'site':self.cfg,'site_data':self.site_data}
        self.init_templates()
        self.process_fragments()
        gallery_path=os.path.join(self.content_dir,self.cfg['media_path'],self.cfg['gallery_path'])
        self.log('INFO','marmite::gallery','Processing galleries from: '+gallery_path)
        if not os.path.isdir(gallery_path):self.log('INFO','marmite::gallery','Gallery directory does not exist: '+gallery_path)
        return self

    def sorted_group(self,kind,order='desc'):
        values=self.groups.get(kind,{})
        if kind=='archive':return sorted(values.items(),key=lambda x:x[0],reverse=order!='asc')
        if kind=='tag':
            # Equal-size groups are not specified by the public interface.
            return sorted(values.items(),key=lambda x:((len(x[1]) if order=='asc' else -len(x[1])),x[0]))
        return sorted(values.items(),key=lambda x:((len(x[1]) if order=='asc' else -len(x[1])),x[0]))
    def url_groups(self,kind):
        if kind=='tag':
            result=[];seen=set()
            for name,items in self.sorted_group(kind):
                slug=slugify(name)
                if slug in seen:continue
                seen.add(slug);result.append((name,items))
            return result
        return sorted(self.groups.get(kind,{}).items(),reverse=kind=='archive')
    def create_urls(self):
        u={k:[] for k in URL_KINDS};page_size=self.cfg['pagination']
        if not page_size:raise ZeroDivisionError()
