        u['pages']=[c['slug']+'.html' for c in self.pages]
        if self.pages:u['pages'].append('pages.html')
        for kind,key,index in [('tag','tags','tags'),('author','authors','authors'),('series','series','series'),('stream','streams','streams'),('archive','archives','archive')]:
