        return Markdown(site.cfg.get('markdown_parser'),lambda s:site.log('WARN','marmite::parser',s)).render(result)
    macro=next((m for m in macros if m.value.split('(',1)[0].strip()==name),macros[0])
    signature=re.match(r'\w+\s*\((.*)\)',macro.value)
    context=ctx.copy()
    if signature:
        from .yamlio import split_unquoted
        for arg in split_unquoted(signature[1]):
            if not arg.strip():continue
            key,eq,default=arg.partition('=');key=key.strip()
