    try:return site.engine.nodes(macro.children,context)
    except TemplateError:raise RenderFailure("Failed to render shortcode '"+name+"': Failed to render '__tera_one_off'")


def render_builtin(name,p,site,ctx):
    failure="Failed to render shortcode '"+name+"': Failed to render '__tera_one_off'"
    def link(path):return site.url_for(ctx,path=path)
