        return '\n\n    \n\n<iframe data-testid="embed-iframe" style="border-radius:12px" src="'+url+'?utm_source=generator&theme=0" width="'+p.get('width','100%')+'" height="'+p.get('height','352')+'" frameBorder="0" allowfullscreen="" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe>\n'
    if name=='toc':
        toc=ctx.get('content',{}).get('toc') or ''
        return '\n<div class="content-toc">\n'+toc+'\n</div>\n'
    if name=='socials':
        return '<h2><a href="#my-social-networks" aria-hidden="true" class="anchor" id="my-social-networks"></a>My social networks</h2>\n<p>Social networks not configured in marmite.yaml</p>\n'
    if name=='posts':
        posts=[c for c in site.posts if c['stream']!='draft']
        if p.get('ord')=='asc':posts=list(reversed(posts))
        if 'items' in p and posts:raise RenderFailure(failure+': error while rendering macro `sc::posts`')
        posts=posts[:10]
        text='\n\n<ul class="posts-list">\n'
        if not posts:text+='\n<li>No posts found</li>\n'
        else:
            for c in posts:text+='\n<li><a href="'+link(c['slug']+'.html')+'">'+c['title']+'</a> - '+date_format(c['date'],'%Y-%m-%d')+'</li>\n'
        return text+'\n</ul>\n'
    if name=='pages':
