            text+=('\n' if kind=='stream' else '\n\n')+'<li><a href="'+link(path)+'">'+group+'</a> ('+str(len(contents))+' posts)</li>\n'
        return text+'\n</ul>\n'
    if name=='card':
        if not p.get('slug'):raise RenderFailure(failure)
        c=site.get_content(ctx,p['slug'])
        if not c:raise RenderFailure(failure+': error while rendering macro `sc::card`')
        title=p.get('title',c['title']);image=p.get('image',c['card_image'] or '')
        text=p.get('text',c['description'] or date_format(c['date'],'%Y-%m-%d'))
        typ='post' if c['date'] else 'page'
        prefix='\n\n    \n    \n    \n        \n    \n    \n        \n    \n    \n        \n    \n    \n        \n    \n    \n    \n\n'
        return prefix+'''<div class="card" style="display: flex; align-items: center; border: 1px solid #ddd; border-radius: 8px; padding: 16px; margin: 16px 0; text-decoration: none; color: inherit;">
    <a href="HREF"  style="display: flex; align-items: center; text-decoration: none; color: inherit; width: 100%;">
        <div class="card-image" style="flex-shrink: 0; margin-right: 16px;">
            <img src="IMAGE" alt="TITLE" style="width: 100px; height: 100px; object-fit: cover; border-radius: 4px;">
        </div>
        <div class="card-content" style="flex: 1;">
            <div class="card-type" style="font-size: 0.75em; color: #999; text-transform: uppercase; font-weight: 600; margin-bottom: 2px;">TYPE</div>
            <div class="card-title" style="font-weight: bold; font-size: 1.1em; margin-bottom: 4px;">TITLE</div>
            <div class="card-text" style="color: #666; font-size: 0.9em;">TEXT</div>
