'''.replace('HREF',link(c['slug']+'.html')).replace('IMAGE',image).replace('TITLE',title).replace('TYPE',typ).replace('TEXT',text)
    if name=='gallery':raise RenderFailure(failure)
    raise RenderFailure("Shortcode '"+name+"' not found")


def expand(text,site,context):
    try:custom=collect(site)
    except CollectionError as exc:
        site.log('ERROR','marmite::site','Failed to collect shortcodes: '+str(exc));custom={};site.shortcode_files={}
    pattern=site.cfg['shortcode_pattern'] or PATTERN
    try:regex=re.compile(pattern)
    except re.error:return text
    def replace(match):
        name=match[1];raw=match[2] if match.lastindex and match.lastindex>1 else ''
        params=parse_params(raw)
        try:
            if name in custom:return render_custom(name,custom[name],params,site,context)
            # Escaped quotes left by a JSON template are not valid macro argument literals.
            if raw and '\\"' in raw:raise RenderFailure("Failed to render shortcode '"+name+"': Failed to parse '__tera_one_off'")
            return render_builtin(name,params,site,context)
        except (RenderFailure,TemplateError) as exc:
            message=str(exc);site.log('WARN','marmite::shortcodes',"Shortcode '"+name+"' failed to render: "+message)
            return error_block(message)
    return regex.sub(replace,text)
